Below is a derivation of \cref{eq:vb}, the reduced variance variational bound for diffusion models. This material is from \citet{sohl2015deep}; we include it here only for completeness.
\begin{align}
L &= \Eb{q}{ - \log \frac{p_\theta(\bx_{0:T})}{q(\bx_{1:T} | \bx_0)}} \\
  &= \Eb{q}{ -\log p(\bx_T) - \sum_{t \geq 1} \log \frac{p_\theta(\bx_{t-1} | \bx_t)}{q(\bx_t|\bx_{t-1})} } \\
  &= \Eb{q}{ -\log p(\bx_T) - \sum_{t > 1} \log \frac{p_\theta(\bx_{t-1} | \bx_t)}{q(\bx_t|\bx_{t-1})} - \log\frac{p_\theta(\bx_0|\bx_1)}{q(\bx_1|\bx_0)} } \\
  &= \Eb{q}{ -\log p(\bx_T) - \sum_{t > 1} \log \frac{p_\theta(\bx_{t-1} | \bx_t)}{q(\bx_{t-1}|\bx_t,\bx_0)}\cdot\frac{q(\bx_{t-1}|\bx_0)}{q(\bx_t|\bx_0)} - \log\frac{p_\theta(\bx_0|\bx_1)}{q(\bx_1|\bx_0)} } \\
  &= \Eb{q}{ -\log \frac{p(\bx_T)}{q(\bx_T|\bx_0)} - \sum_{t > 1} \log \frac{p_\theta(\bx_{t-1} | \bx_t)}{q(\bx_{t-1}|\bx_t,\bx_0)} - \log p_\theta(\bx_0|\bx_1) } \\
  &= \Eb{q}{ \kl{q(\bx_T|\bx_0)}{p(\bx_T)} + \sum_{t > 1} \kl{q(\bx_{t-1}|\bx_t,\bx_0)}{p_\theta(\bx_{t-1} | \bx_t)} - \log p_\theta(\bx_0|\bx_1) }
\end{align}

The training criterion for the discriminator D, given any generator $G$, is to maximize the quantity $V(G, D)$
\begin{align}
V(G, D) =& \int_{\bm{x}} p_\text{data}(\bm{x}) \log(D(\bm{x})) dx + \int_z p_{\bm{z}}(\bm{z}) \log(1 - D(g(\bm{z}))) dz \nonumber \\
		=& \int_{\bm{x}} p_\text{data}(\bm{x}) \log(D(\bm{x})) + p_g(\bm{x}) \log(1 - D(\bm{x})) dx
\end{align}

For any $(a,b) \in \mathbb{R}^2 \setminus \{0, 0\} $, the function $y \rightarrow a \log (y) + b \log (1-y)$ achieves its maximum in $[0,1]$ at $\frac{a}{a+b}$. The discriminator does not need to be defined outside of $Supp(p_\text{data}) \cup Supp(p_g)$, concluding the proof.

For $p_g=p_\text{data}$, $D^*_G(\bm{x})=\frac{1}{2}$, (consider Eq.~\ref{eq:optimal-D}). Hence, by inspecting Eq.~\ref{eq:G-criterion} at $D^*_G(\bm{x})=\frac{1}{2}$, we find $C(G)=\log\frac{1}{2} + \log\frac{1}{2}= - \log 4$. To see that this is the best possible value of $C(G)$, reached only for $p_g = p_\text{data}$, observe that
\[
 \mathbb{E}_{\bm{x} \sim p_\text{data}} \left[ - \log 2 \right] + \mathbb{E}_{\bm{x} \sim p_g} \left[ - \log 2 \right] = -\log 4
\]
and that by subtracting this expression from $C(G) = V(D_G^*,G)$, we obtain:

\begin{equation}
C(G) = -\log(4) + KL \left(p_\text{data} \left \| \frac{p_\text{data} + p_g}{2} \right. \right) + KL \left(p_g \left \| \frac{p_\text{data} + p_g}{2} \right. \right)
\end{equation}

where KL is the Kullback--Leibler divergence. We recognize in the previous expression the Jensen--Shannon divergence between the model's distribution and the data generating process:

\begin{equation}
C(G) = - \log(4) + 2 \cdot JSD \left(p_\text{data} \left \| p_g \right. \right)
\end{equation}

Since the Jensen--Shannon divergence between two distributions is always non-negative and zero only when they are equal, we have shown that $ C^* = - \log (4)$ is the global minimum of $C(G)$ and that the only solution is $p_g=p_\text{data}$, i.e., the generative model perfectly replicating the data generating process.

Recall that we want to show that given a function $f \in \mc F_{m PE}$, we can find a Transformer network $g \in \mc T^{2,1,4}$ such that $ uncdist_p(f, g) \leq \epsilon$. Without loss of generality, we can assume that the compact support of $f$ is contained in $[0, 1]^{d 	imes n}$. We achieve our desired objective in three key steps: \vspace{-2pt} 
oindent{ f Step 1.~Approximate $\mc F_{m PE}$ with piece-wise constant functions.}~We first use (a variant of) the classical result that any continuous function can be approximated up to arbitrary accuracy by piece-wise constant functions. For $\delta > 0$, we define the following class of piece-wise constant functions.  egin{align*} \overline{\mc F}_{m PE}(\delta) \defeq \left \{ f: \mX \mapsto \sum
olimits_{\mL \in \sG_{\delta}} \mA_\mL \indic{\mX \in \sS_\mL} \mid f 	ext{ is permutation equivariant, } \mA_\mL \in eals^{d 	imes n} ight \}, \end{align*} where $\sG_{\delta} \defeq \{0, \delta, \dots, 1-\delta \}^{d 	imes n}$ and, for a grid point $\mL \in \sG_{\delta}$, $\sS_\mL \defeq \prod_{j=1}^d \prod_{k=1}^n [\emL_{j,k}, \emL_{j,k}+\delta) \subset [0,1]^{d 	imes n}$ denotes the associated cube of width $\delta$. Let $\overline{f} \in \overline{\mc F}_{m PE}(\delta)$ be such that $ uncdist_{p}(f, \overline{f}) \leq \epsilon/3$. \vspace{-2pt} 
oindent{ f Step 2.~Approximate $\overline {\mc F}_{m PE} (\delta)$ with {\em modified} Transformers.} We then consider a slightly modified architecture for Transformer networks, where the softmax operator $\sfmx[\cdot]$ and $elu(\cdot)$ are replaced by the hardmax operator $\hdmx[\cdot]$ and an activation function $\phi \in \Phi$, respectively. Here, the set of allowed activations $\Phi$ consists of all piece-wise linear functions with at most three pieces, where at least one piece is constant. Let $\overline{\mc T}^{h, m, r}$ denote the function class corresponding to the sequence-to-sequence functions defined by the modified Transformer networks. The following result establishes that the modified Transformer networks in $\overline{\mc T}^{2, 1, 1}$ can closely approximate functions in $\overline {\mc F}_{m PE}(\delta)$.  egin{proposition} For each $\overline f \in \overline {\mc F}_{m PE} (\delta)$ and $1\leq p < \infty$, $\exists$ $\overline g \in \overline {\mc T}^{2,1,1}$ such that $ uncdist_p(\overline f, \overline g) = O(\delta^{d/p})$. \end{proposition} \vspace{-2pt} 
oindent{ f Step 3.~Approximate modified Transformers with (original) Transformers.} Finally, we show that $\overline{g} \in \overline {\mc T}^{2,1,1}$ can be approximated by $\mc T^{2, 1, 4}$. Let $g \in {\mc T}^{2,1,4}$ be such that $ uncdist_{p}(\overline{g}, g)\leq \epsilon/3$. Theorem~ef{thm:univapprox} now follows from these three steps, because we have  egin{equation*}  uncdist_p(f, g) \leq  uncdist_p(f, \overline f) +  uncdist_p(\overline f, \overline g) +  uncdist_p(\overline g,g) \leq {2\epsilon}/{3} + O(\delta^{d/p}). \end{equation*} Choosing $\delta$ small enough ensures that $ uncdist_p(f, g) \leq \epsilon$. \qed

\paragraph{Selective shift operation.} Before starting the proof, we first describe the key component of our proof, which we refer to the \emph{selective shift operation}. Consider the following function, which can be expressed with a multiplicative attention head, with head size $m = 1$ and hardmax $\hdmx$:  egin{align*} \psi(\mZ; b_Q) &= \ve^{(1)} \vu^T \mZ \hdmx [ (\vu^T \mZ)^T (\vu^T \mZ - b_Q \vone_n^T) ] \end{align*} where $\vu \in eals^d$ is a vector that we will choose later, and $\ve^{(1)} = (1, 0, 0, \dots, 0) \in eals^d$ is the standard basis vector. To see what this function computes, first consider the $j$-th column of the attention score matrix: $(\vu^T \mZ)^T (\vu^T \mZ_{:,j} - b_Q)$. Note that, if $\vu^T \mZ_{:,j}>b_Q$, $\hdmx$ will calculate $\argmax$ of $\vu^T \mZ$, whereas if $\vu^T \mZ_{:,j}<b_Q$, it will calculate $\argmin$. Therefore, the $(1,j)$-th entry of $\psi(\mZ; b_Q) \in eals^{d 	imes n}$ can be written as  egin{equation*} \psi(\mZ; b_Q)_{1, j} = \vu^T \mZ \hdmx [ (\vu^T \mZ)^T (\vu^T \mZ_{:,j} - b_Q) ] =  egin{cases} \max_k \vu^T \mZ_{:,k} & 	ext{ if } \vu^T \mZ_{:,j} > b_Q, \ \min_k \vu^T \mZ_{:,k} & 	ext{ if } \vu^T \mZ_{:,j} < b_Q, \end{cases} \end{equation*} for $j \in [n]$. Note that due to $\ve^{(1)}$, all rows of $\psi(\mZ; b_Q)$ except the first row are zero. From this observation, one can define a function parametrized by $b_Q$ and $b'_Q$, where $b_Q < b'_Q$, which consists of two attention heads:  egin{align*} &\Psi(\mZ; b_Q, b'_Q) \defeq \psi(\mZ; b_Q) - \psi(\mZ; b'_Q),\ &\Psi(\mZ; b_Q, b'_Q)_{1, j} =  egin{cases} \max_k \vu^T \mZ_{:,k} - \min_k \vu^T \mZ_{:,k} & 	ext{ if } b_Q < \vu^T \mZ_{:,j} < b'_Q, \ 0 & 	ext{ if } \vu^T \mZ_{:,j} < b_Q 	ext{ or } \vu^T \mZ_{:,j} > b'_Q. \end{cases} \end{align*} What this means is that, if we define an attention layer of the form $\mZ \mapsto \mZ + \Psi(\mZ;b_Q,b'_Q)$, then any column $\mZ_{:,j}$ satisfying $\vu^T \mZ_{:,j} \in (b_Q,b'_Q)$ is shifted up in its first coordinate $\mZ_{1,j}$ by $\max_k \vu^T \mZ_{:,k} - \min_k \vu^T \mZ_{:,k}$, 	extbf{while all the other coordinates stay untouched}. We call this the selective shift operation, because we can choose $b_Q$ and $b'_Q$ to selectively shift certain entries of the input. \paragraph{Bijective column id mapping.} Recall that the input to this step is from the range of $g_{m q}$ (Lemma~ef{lemma:quantize}), which is $\sG^+_{\delta} = \{ -\delta^{-nd}, 0, \delta, \dots, 1-\delta \}^{d 	imes n}$. Now consider $\mL \in \sG^+_{\delta}$ and $\vu = (1, \delta^{-1}, \delta^{-2}, \dots, \delta^{-d+1})$. For any $j \in [n]$, it is easy to check two following facts:  egin{enumerate} \item If $\mL_{i,j} 
eq -\delta^{-nd}$ for all $i \in [d]$, i.e., $\mL_{:,j} \in \{0, \delta, \dots, 1-\delta\}^d$, then $\vu^T \mL_{:,j} \in [0:\delta:\delta^{-d+1} - \delta]$, and the map $\mL_{:,j} \mapsto \vu^T \mL_{:,j}$ from $\{0, \delta, \dots, 1-\delta\}^d$ to $[0:\delta:\delta^{-d+1} - \delta]$ is a bijection. \item If there exists $i \in [d]$ such that $\mL_{i,j} = -\delta^{-nd}$, then $\vu^T \mL_{:,j} \leq -\delta^{-nd} + \delta^{-d+1} - 1 < 0$. \end{enumerate} Therefore, one can say that $\vu^T \mL_{:,j}$ gives the ``column id'' for each possible value of $\mL_{:,j} \in \{0, \delta, \dots, 1-\delta\}^d$. The rough idea of the construction is to apply the selective shift operation to each column id, by setting $\vu$ in the definition of $\Psi(\cdot)$ to be $(1, \delta^{-1}, \delta^{-2}, \dots, \delta^{-d+1})$ and choosing $b_Q = l - \delta/2$ and $b'_Q = l + \delta/2$ for each $l \in [0:\delta:\delta^{-d+1} - \delta]$. More concretely, we stack $(1/\delta)^d$ attention layers, with attention parts $\delta^{-d} \Psi(\cdot;l-\delta/2,l+\delta/2)$ for each $l \in [0:\delta:\delta^{-d+1} - \delta]$, in increasing order of $l$. After that, we add an extra single-head attention layer with attention part $\delta^{-(n+1)d} \psi(\cdot;0)$. We now divide possible input values $\mL \in \sG^+_{\delta}$ into three disjoint categories, and show how these layers change the input values at the end of all the layers. Recall the hierarchy $\wt {\sG}_{\delta} \subset \sG_{\delta} \subset \sG^+_{\delta}$. The categories are defined as follows:  egin{enumerate} \item $\mL \in \wt {\sG}_{\delta}$. All entries are between $0$ and $1-\delta$, and all columns are unique. \item $\mL \in \sG_{\delta} \setminus \wt {\sG}_{\delta}$. All entries are between $0$ and $1-\delta$, but there are duplicate columns. \item $\mL \in \sG^+_{\delta} \setminus \sG_{\delta}$. The point has at least one entry that equals to $-\delta^{-nd}$. \end{enumerate} \subsubsection{Category 1} In Category~1, we have $\mL \in \wt {\sG}_{\delta}$. Let $l_j \defeq \vu^T \mL_{:,j}$. Due to permutation equivariance, we can assume without loss of generality that $l_j$'s are in increasing order: $l_1 < l_2 < \cdots < l_n$. The first $(1/\delta)^d$ layers sweep the set $[0:\delta:\delta^{-d+1}-\delta]$ and apply selective shift operation on each element in the set. This means that selective shift operation will be applied to $l_1$ first, then $l_2$, and then $l_3$, and so on, regardless of the specific values of $l_j$'s. \paragraph{First shift operation.} In the first selective shift operation, the $(1,1)$-th entry of $\mL$ ($\emL_{1,1}$) is shifted by the operation, while the other entries are left untouched. The updated value $\wt \emL_{1,1}$ is  egin{align*} \wt \emL_{1,1} = \emL_{1,1} + \delta^{-d} (\max
olimits_k \vu^T \mL_{:,k} - \min
olimits_k \vu^T \mL_{:,k}) = \emL_{1,1} + \delta^{-d} (l_n - l_1). \end{align*} Therefore, after the operation, the output of the layer is $ egin{bmatrix} \wt \mL_{:,1} & \mL_{:,2} & \dots & \mL_{:,n} \end{bmatrix}$, and the new value of the first column $\wt \mL_{:,1}$ results in  egin{align*} \vu^T \wt \mL_{:,1} = \wt \emL_{1,1} + \sum_{i=2}^d \delta^{-i+1} \emL_{i,1} = \emL_{1,1} + \delta^{-d} (l_n - l_1) + \sum_{i=2}^d \delta^{-i+1} \emL_{i,1} = l_1 + \delta^{-d} (l_n - l_1). \end{align*} Let us denote the updated ``column id'' $\vu^T \wt \mL_{:,1}$ as $\wt l_1$. We can show that $l_n < \wt l_1$, because  egin{align*} \wt l_1 \defeq l_1 + \delta^{-d} (l_n - l_1) \geq 0 + \delta^{-d} \cdot \delta = \delta^{-d + 1} > l_n. \end{align*} Therefore, after updating,  egin{equation*} \max \vu^T  egin{bmatrix} \wt \mL_{:,1} & \mL_{:,2} & \dots & \mL_{:,n} \end{bmatrix} = \max \{ \wt l_1, l_2, \dots, l_n \} = \wt l_1, \end{equation*} and the new minimum is $l_2$. \paragraph{Second shift operation.} The second selective shift operation is applied to $l_2$, by which only one entry $\emL_{1,2}$ will be shifted. The updated value $\wt \emL_{1,2}$ is  egin{equation*} \wt \emL_{1,2} = \emL_{1,2} + \delta^{-d} (\wt l_1 - l_2) = \emL_{1,2} + \delta^{-d} (l_1 - l_2) + \delta^{-2d} (l_n - l_1). \end{equation*} After updating, the new inner product of $\vu$ and $\wt \mL_{:,2}$ results in  egin{equation*} \wt l_2 \defeq \vu^T \wt \mL_{:,2} = l_2 + \delta^{-d} (l_1 - l_2) + \delta^{-2d} (l_n - l_1). \end{equation*} We can show that $\wt l_1 < \wt l_2$, because  egin{align*} &l_1 + \delta^{-d} (l_n - l_1) < l_2 + \delta^{-d} (l_1 - l_2) + \delta^{-2d} (l_n - l_1)\ \iff~& (\delta^{-d}-1) (l_2 - l_1) < \delta^{-d}(\delta^{-d}-1) (l_n - l_1), \end{align*} and the last inequality is true because $\delta^{-d} > 1$ and $l_n > l_2$. Since we have $\wt l_1 < \wt l_2$, and the new maximum in $\vu^T  egin{bmatrix} \wt \mL_{:,1} & \wt \mL_{:,2} & \mL_{:,3} & \dots & \mL_{:,n} \end{bmatrix}$ is now $\wt l_2$, and the new minimum is $l_3$. \paragraph{Repeating the process.} More generally, we can repeat this process, and show that the $j$-th shift operation shifts $\emL_{1,j}$ by $\delta^{-d} (\wt l_{j-1} - l_j)$, and results in the new column id  egin{equation*} \wt l_j \defeq \vu^T \wt \mL_{:,j} = l_j + \sum_{k=1}^{j-1} \delta^{-kd}(l_{j-k}-l_{j-k+1}) + \delta^{-jd} (l_n-l_1). \end{equation*} In the general case, $\wt l_{j-1} < \wt l_j$ holds $j = [2:n]$, because  egin{align*} &\wt l_{j-1} = l_{j-1} + \sum_{k=2}^{j-1} \delta^{-kd+d}(l_{j-k}-l_{j-k+1}) + \delta^{-(j-1)d} (l_n-l_1)\ &< \wt l_j = l_j + \sum_{k=1}^{j-1} \delta^{-kd}(l_{j-k}-l_{j-k+1}) + \delta^{-jd} (l_n-l_1)\ \iff~& \sum_{k=1}^{j-1} \delta^{-kd+d} (\delta^{-d}-1)(l_{j-k+1}-l_{j-k}) < \delta^{-(j-1)d}(\delta^{-d}-1)(l_n-l_1), \end{align*} and the last inequality holds because  egin{equation*} \delta^{-(j-1)d}(l_n-l_1) > \delta^{-(j-1)d} \sum_{k=1}^{j-1}(l_{j-k+1} - l_{j-k}) > \sum_{k=1}^{j-1} \delta^{-kd+d} (l_{j-k+1}-l_{j-k}). \end{equation*} Therefore, after the $j$-th selective shift operation, $\wt l_j$ is the new maximum among $\{\wt l_1, \dots, \wt l_j, l_{j+1}, \dots, l_n\}$ and $l_{j+1}$ is the new minimum, which makes us possible to continue the process until the $n$-th operation. \paragraph{After $n$ shift operations.} As a result, after the whole sweep from $0$ to $\delta^{-d+1}-\delta$ by the first $(1/\delta)^d$ layers, a total of $n$ shift operations are applied, and the input $\mL$ is mapped to a new point $\wt \mL$, where $\vu^T \wt \mL =  egin{bmatrix}\wt l_1 & \wt l_2 & \dots & \wt l_n \end{bmatrix}$ and $\wt l_1 < \wt l_2 < \dots < \wt l_n$. We can now prove the following technical lemma, whose proof is deferred to Appendix~ef{sec:proof-sublemma:1}:  egin{lemma} After $n$ shift operations, $\wt l_n = \vu^T \wt \mL_{:,n}$ satisfies the following bounds:  egin{equation*} \delta^{-(n-1)d+1}(\delta^{-d} - 1) \leq \wt l_n \leq \delta^{-nd + 1}(\delta^{-d}-1) - \delta (\delta^{-d} - 1)^2. \end{equation*} Also, the map from $ egin{bmatrix} l_1 & l_2 & \cdots & l_n \end{bmatrix} \in [0:\delta:\delta^{-d+1}-\delta]$ (where $l_1 < l_2 < \dots < l_n$) to $\wt l_n$ is one-to-one. \end{lemma} \paragraph{Global shifting by the last layer.} As mentioned earlier, after this sweep, there is another attention layer with attention part $\delta^{-(n+1)d} \psi(\cdot;0)$. Since $0<\wt l_1 < \cdots < \wt l_n$, what it does to $\wt \mL$ is that it adds $\delta^{-(n+1)d} \max_k \vu^T \wt \mL_{:,k} = \delta^{-(n+1)d} \wt l_n$ to each entry in the first row of $\wt \mL$. The output of this layer is defined to be the function $g_{m c}(\mL)$. Now, in summary, for any $\mL \in \wt {\sG}_{\delta}$, $i \in [d]$, and $j \in [n]$, we have  egin{equation*} g_{m c}(\mL)_{i,j} =  egin{cases} \emL_{1,j} + \sum_{k=1}^{j-1} \delta^{-kd}(l_{j-k}-l_{j-k+1}) + \delta^{-jd} (l_n-l_1) + \delta^{-(n+1)d} \wt l_n & 	ext { if } i = 1,\ \emL_{i,j} & 	ext { if } i \in [2,d], \end{cases} \end{equation*} and for any $\mL \in \wt {\sG}_{\delta}$ and $j \in [n]$,  egin{equation*} \vu^T g_{m c}(\mL)_{:,j} = \wt l_{j} + \delta^{-(n+1)d} \wt l_n. \end{equation*} \paragraph{Checking Properties~ef{lemma:contextmap}.ef{cond:1} and ef{lemma:contextmap}.ef{cond:2}.} Given this result so far, it is now left to check if the constructed network is really a permutation equivariant contextual mapping, i.e., if it satisfies Properties~ef{lemma:contextmap}.ef{cond:1} and ef{lemma:contextmap}.ef{cond:2} in Lemma~ef{lemma:contextmap}. First, for any $\mL \in \wt {\sG}_{\delta}$, Property~ef{lemma:contextmap}.ef{cond:1} holds because we already know $\wt l_1 < \wt l_2 < \dots < \wt l_n$, so they are all distinct. As for Property~ef{lemma:contextmap}.ef{cond:2}, note that the upper bound on $\wt l_n$ from Lemma~ef{sublemma:1} also holds for other $\wt l_j$'s, so  egin{equation*} \vu^T g_{m c}(\mL)_{:,j} \in [\delta^{-(n+1)d} \wt l_n, \delta^{-(n+1)d} \wt l_n + \delta^{-(n+1)d+1}), \end{equation*} for all $j \in [n]$. Now, from Lemma~ef{sublemma:1}, two $\mL, \mL' \in \wt {\sG}_{\delta}$ (that are not permutations of each other) map to different $\wt l_n$ and $\wt l'_n$, and they differ at least by $\delta$. This means that two intervals $[\delta^{-(n+1)d} \wt l_n, \delta^{-(n+1)d} \wt l_n + \delta^{-(n+1)d+1})$ and $[\delta^{-(n+1)d} \wt l'_n, \delta^{-(n+1)d} \wt l'_n + \delta^{-(n+1)d+1})$ are guaranteed to be disjoint, so the entries of $\vu^T g_{m c}(\mL)$ and $\vu^T g_{m c}(\mL')$ are all distinct. This proves Property~ef{lemma:contextmap}.ef{cond:2}. Therefore, we finished showing that the map $g_{m c}(\cdot)$ we constructed using $(1/\delta)^d+1$ attention layers implements a permutation equivariant contextual mapping on $\wt {\sG}_{\delta}$. \paragraph{Checking Property~ef{lemma:contextmap}.ef{cond:3}.} It is now left to check if the map $g_{m c}$ satisfies the other properties. At this point, we can check Property~ef{lemma:contextmap}.ef{cond:3}. From $\vu^T g_{m c}(\mL)_{:,j} \in [\delta^{-(n+1)d} \wt l_n, \delta^{-(n+1)d} \wt l_n + \delta^{-(n+1)d+1})$ and Lemma~ef{sublemma:1}, we can show that for any $\mL \in \wt {\sG}_{\delta}$, we have  egin{align*} \delta^{-2nd+1}(\delta^{-d} - 1) \leq \vu^T g_{m c}(\mL)_{:,j} &< \delta^{-(n+1)d}(\delta^{-nd + 1}(\delta^{-d}-1) - \delta (\delta^{-d} - 1)^2) + \delta^{-(n+1)d+1}\ &\leq \delta^{-(2n+1)d+1}(\delta^{-d}-1), \end{align*} where we used $\delta^{-1} \geq 2$. This proves that all $\vu^T g_{m c}(\mL)_{:,j}$ are between $t_l = \delta^{-2nd+1}(\delta^{-d} - 1)$ and $t_r = \delta^{-(2n+1)d+1}(\delta^{-d}-1)$. For the remaining input points $\mL \in \sG^+_{\delta} \setminus \wt {\sG}_{\delta}$, we will check that $\vu^T g_{m c}(\mL)_{:,j}$ is outside the interval $[t_l , t_r]$ (Property~ef{lemma:contextmap}.ef{cond:4}). \subsubsection{Category 2} In Category~2, we have $\mL \in \sG_{\delta}\setminus \wt {\sG}_{\delta}$. Here, all entries are between $0$ and $1-\delta$, but there are duplicate columns. Again, let $l_j \defeq \vu^T \mL_{:,j}$, and assume without loss of generality that $l_1 \leq l_2 \leq \dots \leq l_n$. For the input $\mL$ in Category~2, there exist some $j, j' \in [n]$, $j 
eq j'$, such that $l_j = l_{j'}$. This means that when the input passes through the attention layer $\delta^{-d}\Psi(\cdot; l_j - \delta/2, l_j + \delta/2)$, the selective shift operation for $l_j$ is applied to both $j$-th and $j'$-th columns; the two columns are coupled together. More generally, suppose we have $n' < n$ distinct columns. \paragraph{If $n'= 1$.} In the extreme case of $n' = 1$, we have $\max_j l_j = \min_j l_j$, so the selective shift operation applied at $l_j$ does not shift the entry at all; therefore, at the end of the first $(1/\delta)^d$ attention layers, $\wt \mL = \mL$. \paragraph{If $1 < n' \leq n - 1$.} When $1 < n' \leq n-1$, let the $n'$ distinct values of $l_j$'s be $l'_1, \dots, l'_{n'}$. The shift operation is applied $n'$ times, to $l'_1, \dots, l'_{n'}$, and shifts one or more entries at a time. After the first $(1/\delta)^d$ layers, the output $\wt \mL$ has $n'$ distinct $\wt l_j = \vu^T \wt \mL_{:,j}$, $0 \leq \wt l_1 \leq \wt l_2 \leq \dots \leq \wt l_n$, whose distinct values are the same as the numbers we get when we apply shift operations to a length-$n'$ sequence $ egin{bmatrix} l'_1 & \dots & l'_{n'} \end{bmatrix}$. Then, applying the same calculations from Category~1 shows that  egin{equation*} \wt l_n = \vu^T \wt \mL_{:,n} = l'_{n'} + \sum_{k=1}^{n'-1} \delta^{-kd}(l'_{n'-k}-l'_{n'-k+1}) + \delta^{-n'd} (l'_{n'}-l'_1), \end{equation*} and it follows from the upper bound in Lemma~ef{sublemma:1} that  egin{equation*} \wt l_n \leq \delta^{-n'd + 1}(\delta^{-d}-1) - \delta (\delta^{-d} - 1)^2 < \delta^{-(n-1)d + 1}(\delta^{-d}-1). \end{equation*} Note that the RHS matches the lower bound in Lemma~ef{sublemma:1}. This implies that the value of $\wt l_n$ calculated from the input $\mL \in \sG_{\delta}\setminus \wt {\sG}_{\delta}$ (Category~2) is always strictly less (by at least $\delta$) than that calculated from $\mL \in \wt {\sG}_{\delta}$ (Category~1). \paragraph{Checking Property~ef{lemma:contextmap}.ef{cond:4}.} After the global shifting by the last layer with attention part $\delta^{-(n+1)d} \psi(\cdot;0)$, we get the output $g_{m c}(\mL)$ which satisfies  egin{align*} \vu^T g_{m c}(\mL)_{:,j} = \wt l_{j} + \delta^{-(n+1)d} \wt l_n &\leq (\delta^{-(n+1)d} + 1) (\delta^{-(n-1)d + 1}(\delta^{-d}-1) - \delta (\delta^{-d} - 1)^2)\ &< \delta^{-2nd+1}(\delta^{-d}-1) \eqdef t_l. \end{align*} where the RHS is a lower bound on possible values of $\vu^T g_{m c}(\mL)_{:,j}$ for $\mL \in \wt {\sG}_{\delta}$ (Category~1). This means that the entries of $\vu^T g_{m c}(\mL)$ for Category~2 are outside $[t_l, t_r]$, which satisfies Property~ef{lemma:contextmap}.ef{cond:4}. \subsubsection{Category~3} In Category~3, we have $\mL \in \sG^+_{\delta} \setminus \sG_{\delta}$; the point $\mL$ has at least one entry that equals to $-\delta^{-nd}$. Let $l_j \defeq \vu^T \mL_{:,j}$, and recall that whenever a column $\mL_{:,j}$ has an entry that equals to $-\delta^{-nd}$, we have $l_j = \vu^T \mL_{:,j} \leq -\delta^{-nd} + \delta^{-d+1} - 1 < 0$. Assume without loss of generality that $l_1 \leq l_2 \leq \dots \leq l_n$. Recall that the selective shift operation is applied to each element of $[0:\delta:\delta^{-d+1}-\delta]$, not to negative values. In case of Category~3, we have $\min_k \vu^T \mL_{:,k} = l_1 < 0$, and $l_1$ never gets shifted upwards, so it remains as the minimum for the whole time. \paragraph{If all $l_j$'s are negative.} In case where all $l_j$'s are negative, selective shift operation never changes the input $\mL$, so we get $\wt \mL = \mL$. Since we have $\vu^T \wt \mL < \vzero_n^T$ (entry-wise), the last layer with attention part $\delta^{-(n+1)d} \psi(\cdot;0)$ adds $\delta^{-(n+1)d} \min_k \vu^T \wt \mL_{:,k} < 0$ to each entry in the first row of $\wt \mL$, further pushing it to the negative side. Therefore, the final output $g_{m c}(\mL)$ satisfies $\vu^T g_{m c}(\mL) < \vzero_n^T < t_l\vone_n^T$. \paragraph{If not all $l_j$'s are negative.} Now consider the case where at least one $l_j$ is positive. Let $i$ be the index that satisfies $l_{i-1} < 0 \leq l_{i}$. Then, selective shift operation does not affect $l_1, \dots, l_{i-1}$, and then it shifts $l_{i}$ by  egin{equation*} \delta^{-d}(\max_k \vu^T \mL_{:,k} - \min_k \vu^T \mL_{:,k}) = \delta^{-d} (l_n - l_1) \geq \delta^{-d} (0 + \delta^{-nd} - \delta^{-d+1} + 1) \geq \delta^{-(n+1)d+1}, \end{equation*} where we used $\delta^{-1} \geq 2$ at the last inequality. The next shift operations shift $l_{i+1}, \dots, l_n$ by even larger amount, so at the end of the first $(1/\delta)^d$ layers, we have $\delta^{-(n+1)d+1} \leq \wt l_{i} \leq \dots \leq \wt l_n$, while $\wt l_j = l_j < 0$ for $j \in [i-1]$. \paragraph{Shifts by the last layer.} Here, the last layer with attention part $\delta^{-(n+1)d} \psi(\cdot;0)$ acts differently for negative and positive $\wt l_j$'s. For negative $\wt l_j$'s, it adds $\delta^{-(n+1)d} \min_k \wt l_{k} = \delta^{-(n+1)d} l_1 < 0$ to $\wt l_1, \dots, \wt l_{i-1}$, pushing them further to the negative side. For positive $\wt l_j$'s, the layer adds $\delta^{-(n+1)d} \max_k \wt l_{k} = \delta^{-(n+1)d} \wt l_n \geq \delta^{-(2n+2)d+1}$ to $\wt l_{i}, \dots, \wt l_{n}$, so that they are all greater than or equal to $\delta^{-(2n+2)d+1}$. Note that $\delta^{-(2n+2)d+1} > t_r$. \paragraph{Checking Property~ef{lemma:contextmap}.ef{cond:4}.} Therefore, in both cases, we can see that the final output $g_{m c}(\mL)$ satisfies $\vu^T g_{m c}(\mL)_{:,j} 
otin [t_l, t_r]$, for all $j \in [n]$. This completes the verification of Property~ef{lemma:contextmap}.ef{cond:4}.
